use std::fs

fn find(keys: Vec<int>, k: int) -> int {
    let mut i: int = 0
    while i < keys.len() {
        if keys[i] == k {
            return i
        }
        i += 1
    }
    -1
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut cap: int = 0
    let mut first = true
    let mut keys: Vec<int> = []
    let mut vals: Vec<int> = []
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().collect()
        if parts.len() == 0 {
            continue
        }
        if first {
            cap = parts[0].parse::<int>().unwrap_or(1)
            first = false
            continue
        }
        if parts[0] == "put" {
            let k = parts[1].parse::<int>().unwrap_or(0)
            let v = parts[2].parse::<int>().unwrap_or(0)
            let idx = find(keys.clone(), k)
            if idx >= 0 {
                keys.remove(idx)
                vals.remove(idx)
            }
            keys.push(k)
            vals.push(v)
            if keys.len() > cap {
                let ek = keys[0]
                keys.remove(0)
                vals.remove(0)
                println("evict ${ek}")
            }
        } else if parts[0] == "get" {
            let k = parts[1].parse::<int>().unwrap_or(0)
            let idx = find(keys.clone(), k)
            if idx < 0 {
                println("-1")
            } else {
                let v = vals[idx]
                keys.remove(idx)
                vals.remove(idx)
                keys.push(k)
                vals.push(v)
                println("${v}")
            }
        } else if parts[0] == "keys" {
            if keys.len() == 0 {
                println("<empty>")
            } else {
                let mut out: Vec<string> = []
                let mut rev: Vec<int> = []
                for k in keys {
                    rev.insert(0, k)
                }
                for k in rev {
                    out.push("${k}")
                }
                println(out.join(" "))
            }
        }
    }
}

